  <meta name="description" content="The practice and perspective behind our carefully prepared aromatherapy support.">
  <style>
    :root{--bg:#fffefc;--muted:#6f6460;--accent:#8fb48f;--ink:#281f1c}
    body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial;margin:0;background:var(--bg);color:var(--ink);line-height:1.5}
