    .intro{background:linear-gradient(180deg,#fff 0%,#fbfcfb 100%);padding:20px;border-radius:14px;border:1px solid rgba(40,31,28,0.04)}
    h1{margin:0 0 10px;font-size:28px}
    .story{display:grid;grid-template-columns:1fr 300px;gap:20px;margin-top:18px}
    .card{background:#fff;padding:16px;border-radius:12px;border:1px solid rgba(40,31,28,0.04)}
    .values{display:flex;flex-direction:column;gap:10px;margin-top:12px}
    .pill{background:rgba(143,180,143,0.1);padding:8px;border-radius:8px;font-weight:700;color:var(--accent)}
    .framework{margin-top:18px}
    .faq{margin-top:16px;padding:14px;border-radius:10px;background:#fff}

    /* reveal */
    .reveal-on-scroll{opacity:0;transform:translateY(18px);transition:opacity 520ms ease,transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal-on-scroll.revealed{opacity:1;transform:translateY(0)}
    @media (prefers-reduced-motion:reduce){.reveal-on-scroll{transition:none;opacity:1;transform:none}}

    footer{max-width:980px;margin:28px auto;padding:12px;color:var(--muted);font-size:13px}
  </style>
